const cfg = $('Config').first().json;
const all = $input.all().map(i => i.json);
const first = all[0] || {};
if (first.error && !first.bundle_id) {
  const e = first.error;
  return [{ json: { _empty: true, fetch_error: typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e) } }];
}
let rows = all.filter(r => r && r.bundle_id);
const ids = Array.isArray(cfg.bundle_ids) ? cfg.bundle_ids.map(String) : [];
if (ids.length) rows = rows.filter(r => ids.includes(String(r.bundle_id)));
if (!rows.length) return [{ json: { _empty: true, fetch_error: null } }];
return rows.map(r => ({ json: r }));

const raw = $input.all().map(i => i.json).filter(r => r && r.route);
const byBundle = {};
raw.forEach(r => { byBundle[r.bundle_id] = r; });
const rows = Object.values(byBundle);
let fetchError = null;
try { fetchError = $('Filter Requested').first().json.fetch_error || null; } catch (e) { fetchError = null; }
const per_route = {};
const per_result = {};
rows.forEach(r => {
  per_route[r.route] = (per_route[r.route] || 0) + 1;
  per_result[r.result] = (per_result[r.result] || 0) + 1;
});
return [{ json: { total: rows.length, per_route, per_result, fetch_error: fetchError, bundles: rows } }];

const b = $json;
let route = String(b.route || "").toUpperCase();
let reason = null;
if (b.opted_out === true) { route = "SKIP"; reason = "OPTED_OUT"; }
else if (!b.telegram_chat_id) { route = "SKIP"; reason = "NO_TELEGRAM_CHAT_ID"; }
else if (!["SKIP", "STAFF", "AUTO_APPLY", "SUGGEST", "ASK"].includes(route)) { route = "SKIP"; reason = "UNKNOWN_ROUTE_" + route; }
else if (route === "SKIP") reason = "ROUTE_SKIP";
return { json: Object.assign({}, b, { route_final: route, skip_reason: reason }) };

const rg = $('Route Guard').item.json;
const e = $json.error;
const err = e ? (typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e)) : null;
return { json: { bundle_id: rg.bundle_id, route: "SKIP", result: err ? "ERROR" : "SKIPPED", error: err || rg.skip_reason } };

const cfg = $('Config').first().json;
const b = $('Route Guard').item.json;
return { json: {
  chat_id: String(cfg.TELEGRAM_STAFF_CHAT_ID || ""),
  language: "en",
  text: null,
  key: "msg_staff_flag",
  params: { business_name: b.business_name || "?", entity_id: b.entity_id || "?", text: b.intro_text || "" },
  lines: [],
  buttons: [],
  edit_message_id: null,
} };

const rg = $('Route Guard').item.json;
const txt = x => x ? (typeof x === "object" ? (x.message || JSON.stringify(x)) : String(x)) : null;
let sent = null;
try { sent = $('Send Staff Flag').item.json; } catch (err) { sent = null; }
const j = $json;
let result, error = null;
if (sent && sent.ok === true) {
  if (j.error) { result = "STAFF_FLAGGED_NOT_LOGGED"; error = "flag sent but not logged, may repeat next run: " + txt(j.error); }
  else result = "STAFF_FLAGGED";
} else {
  result = "STAFF_SEND_FAILED";
  error = txt((sent && sent.error) || j.error) || "staff message not sent";
}
return { json: { bundle_id: rg.bundle_id, route: "STAFF", result, error } };

const rows = $input.all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null);
if (!rows.length) return [{ json: { _none: true }, pairedItem: { item: 0 } }];
return rows.map(r => ({ json: r, pairedItem: { item: 0 } }));

const expected = $('Check Items').all().length;
const done = $input.all().map(i => i.json).filter(r => r && r.id !== undefined && r.id !== null && !r.error).length;
return [{ json: { ok: done === expected && expected > 0, updated: done, expected }, pairedItem: { item: 0 } }];

const rg = $('Route Guard').item.json;
const j = $json;
const e = j.error;
const errText = e ? (typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e)) : null;
let result, error = null;
if (j._none === true) { result = "AUTO_NO_ITEMS"; error = "bundle has no items"; }
else if (j.ok === false) { result = "AUTO_ITEM_UPDATE_FAILED"; error = "updated " + j.updated + " of " + j.expected; }
else if (j.status) { result = "AUTO_" + j.status; error = j.error || null; }
else if (errText) { result = "ERROR"; error = errText; }
else { result = "AUTO_UNKNOWN"; }
return { json: { bundle_id: rg.bundle_id, route: "AUTO_APPLY", result, error } };

const b = $json;
const id = b.bundle_id;
const buttons = b.route_final === "ASK"
  ? [{ key: "btn_closed", data: "qc:" + id }, { key: "btn_regular", data: "qr:" + id }, { key: "btn_edit", data: "e:" + id }]
  : [{ key: "btn_approve", data: "a:" + id }, { key: "btn_edit", data: "e:" + id }, { key: "btn_decline", data: "d:" + id }];
return { json: {
  chat_id: String(b.telegram_chat_id),
  language: ["fi", "sv", "nb", "en"].includes(b.language) ? b.language : "en",
  text: b.intro_text || "",
  key: null,
  params: {},
  lines: [],
  buttons,
  edit_message_id: null,
} };

const rg = $('Route Guard').item.json;
let sent = null;
try { sent = $('Send Intro').item.json; } catch (err) { sent = null; }
const e = $json.error;
const isNodeError = e && typeof e === "object";
let result, error = null;
if (sent && sent.ok === true && !isNodeError) { result = "SENT"; }
else if (sent && sent.ok === false) { result = "SEND_FAILED"; error = sent.error; }
else { result = "ERROR"; error = e ? (typeof e === "object" ? (e.message || JSON.stringify(e)) : String(e)) : "unknown"; }
if (sent && sent.ok === true && isNodeError) { result = "SENT_STATUS_NOT_SAVED"; error = e.message || JSON.stringify(e); }
return { json: { bundle_id: rg.bundle_id, route: rg.route_final, result, error } };
